import torch


def run(x, dim):
    return torch.count_nonzero(x, dim)


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    dtype = getattr(torch, ctx["x__dtype"])
    if dtype == torch.bool:
        x = torch.randint(0, 2, shape, dtype=torch.int, device=device).to(dtype)
    elif dtype in (torch.int16, torch.int32):
        x = torch.randint(-3, 3, shape, device=device).to(dtype)
    else:
        x = torch.randn(shape, dtype=dtype, device=device)
    return {"x": x}
